-- 023: record WHERE a post's primary image came from.
-- The content manager has to tell an operator "this image was scraped from the
-- source post / generated by AI / uploaded by an admin / linked externally",
-- and until now the only clue was the path shape. `post_images.source` already
-- carries this for gallery images; this brings the same idea to the primary.

ALTER TABLE posts ADD COLUMN media_origin TEXT;

-- Best-effort backfill for existing rows: a remote http(s) URL is an external
-- link, anything else was mirrored by the collector.
UPDATE posts SET media_origin = 'external' WHERE media_path LIKE 'http%';
UPDATE posts SET media_origin = 'collector' WHERE media_path IS NOT NULL AND media_path NOT LIKE 'http%';
